// backend/utils/excelParser.js
const XLSX = require('xlsx');
const path = require('path');
const fs = require('fs');

/**
 * Parses claims_verified.xlsx generated by UiPath Studio robot or offline simulator.
 * Uses SheetJS (xlsx) for robust compatibility with OpenXML, ClosedXML, and ExcelJS workbooks.
 * 
 * @param {String} filePath Path to the verified Excel file
 * @returns {Promise<Array<Object>>} Array of parsed claim verification results
 */
async function parseVerifiedClaimsExcel(filePath) {
  const absolutePath = path.resolve(filePath);

  if (!fs.existsSync(absolutePath)) {
    throw new Error(`RPA verification output file not found at: ${absolutePath}`);
  }

  // Load workbook using SheetJS
  const workbook = XLSX.readFile(absolutePath);

  // Target 'Claims' sheet or fallback to first sheet
  const sheetName = workbook.SheetNames.includes('Claims') 
    ? 'Claims' 
    : workbook.SheetNames[0];

  if (!sheetName) {
    throw new Error('Verification Excel file contains no worksheets.');
  }

  const worksheet = workbook.Sheets[sheetName];
  const rawRows = XLSX.utils.sheet_to_json(worksheet, { defval: '' });

  if (!rawRows || rawRows.length === 0) {
    return [];
  }

  const results = [];

  for (const raw of rawRows) {
    // Case-insensitive property lookup
    const row = {};
    for (const key of Object.keys(raw)) {
      row[key.toLowerCase().replace(/[\s_]/g, '')] = raw[key];
    }

    const claimIdRaw = row['claimid'] || row['id'];
    if (!claimIdRaw) continue; // Skip empty rows

    const claimId = parseInt(claimIdRaw, 10);
    const claimCode = (row['claimcode'] || '').toString().trim();
    const outcomeRaw = (row['outcome'] || '').toString().trim();
    const violationsRaw = (row['violations'] || '').toString().trim();
    const timestampRaw = row['bottimestamp'] || row['timestamp'] || null;
    const checkedAmountRaw = row['checkedamount'] || row['amount'] || 0;
    const policyLimitRaw = row['policylimitapplied'] || row['limitapplied'] || null;

    // Normalize Outcome to match ENUM in database:
    // 'Submitted', 'Verified - Pending Approval', 'Flagged', 'Approved', 'Rejected', 'Needs Correction'
    let outcome = 'Flagged';
    const outcomeLower = outcomeRaw.toLowerCase();
    if (outcomeLower.includes('verified') || outcomeLower.includes('pending approval')) {
      outcome = 'Verified - Pending Approval';
    } else if (outcomeLower.includes('reject')) {
      outcome = 'Rejected';
    } else {
      outcome = 'Flagged';
    }

    // Format violations string
    let violations = violationsRaw;
    if (!violations || violations === 'None' || violations === 'null' || violations === '') {
      violations = null;
    }

    // Clean checked amount and policy limit
    const checkedAmount = parseFloat(checkedAmountRaw) || 0;
    const policyLimitApplied = policyLimitRaw !== null && policyLimitRaw !== '' 
      ? parseFloat(policyLimitRaw) 
      : null;

    // Handle timestamp
    let botRunTimestamp = new Date();
    if (timestampRaw) {
      const parsedDate = new Date(timestampRaw);
      if (!isNaN(parsedDate.getTime())) {
        botRunTimestamp = parsedDate;
      }
    }

    results.push({
      claimId,
      claimCode,
      outcome,
      violations,
      checkedAmount,
      policyLimitApplied,
      botRunTimestamp
    });
  }

  return results;
}

module.exports = {
  parseVerifiedClaimsExcel
};
